package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeRow_TriageGen1Test {

    private KeyedObjects2D keyedObjects2D;

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    @Test
    public void testRemoveRow_ExistingKey() {
        // Arrange
        Comparable rowKey1 = "Row1";
        Comparable rowKey2 = "Row2";
        Comparable colKey1 = "Col1";

        keyedObjects2D.addObject("Data1", rowKey1, colKey1);
        keyedObjects2D.addObject("Data2", rowKey2, colKey1);

        // Act
        keyedObjects2D.removeRow(rowKey1);

        // Assert
        assertEquals("Row count should be 1 after removing one row", 1, keyedObjects2D.getRowCount());
        assertEquals(rowKey2, keyedObjects2D.getRowKey(0));
        assertNull("Data for removed row should be gone", keyedObjects2D.getObject(rowKey1, colKey1));
    }

    @Test
    public void testRemoveRow_LastRow() {
        // Arrange
        Comparable rowKey1 = 1;
        Comparable rowKey2 = 2;
        Comparable colKey1 = "A";

        keyedObjects2D.addObject("V1", rowKey1, colKey1);
        keyedObjects2D.addObject("V2", rowKey2, colKey1);

        // Act
        keyedObjects2D.removeRow(rowKey2);

        // Assert
        assertEquals(1, keyedObjects2D.getRowCount());
        assertEquals(rowKey1, keyedObjects2D.getRowKey(0));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveRow_NonExistentKey() {
        // Arrange
        keyedObjects2D.addObject("V1", "Row1", "Col1");

        // Act
        // getRowIndex usually returns -1 if key not found, 
        // which leads to removeRow(-1) causing IndexOutOfBoundsException
        keyedObjects2D.removeRow("NonExistent");
    }

    @Test
    public void testRemoveRow_EmptyDataset() {
        // Arrange & Act & Assert
        // Attempting to remove from empty dataset should trigger exception via getRowIndex
        try {
            keyedObjects2D.removeRow("AnyKey");
        } catch (Exception e) {
            // Expected behavior depending on implementation of getRowIndex
            // If it returns -1, it throws IndexOutOfBoundsException in removeRow(int)
        }
    }

    @Test
    public void testRemoveRow_MaintainsColumnIntegrity() {
        // Arrange
        Comparable r1 = "R1";
        Comparable r2 = "R2";
        Comparable c1 = "C1";
        Comparable c2 = "C2";

        keyedObjects2D.addObject("R1C1", r1, c1);
        keyedObjects2D.addObject("R1C2", r1, c2);
        keyedObjects2D.addObject("R2C1", r2, c1);
        keyedObjects2D.addObject("R2C2", r2, c2);

        // Act
        keyedObjects2D.removeRow(r1);

        // Assert
        assertEquals(1, keyedObjects2D.getRowCount());
        assertEquals(2, keyedObjects2D.getColumnCount());
        assertEquals("R2C1", keyedObjects2D.getObject(r2, c1));
        assertEquals("R2C2", keyedObjects2D.getObject(r2, c2));
    }
}
